class CertificateModel { final String id,studentId,courseId,certificateNumber,studentName,courseName; final double score; final DateTime issuedAt; const CertificateModel({required this.id,required this.studentId,required this.courseId,required this.certificateNumber,required this.studentName,required this.courseName,required this.score,required this.issuedAt}); Map<String,dynamic> toMap()=>{'studentId':studentId,'courseId':courseId,'certificateNumber':certificateNumber,'studentName':studentName,'courseName':courseName,'score':score,'issuedAt':issuedAt.toIso8601String()}; factory CertificateModel.fromMap(String id,Map<String,dynamic> m)=>CertificateModel(id:id,studentId:m['studentId']??'',courseId:m['courseId']??'',certificateNumber:m['certificateNumber']??'',studentName:m['studentName']??'',courseName:m['courseName']??'',score:(m['score']??0).toDouble(),issuedAt:DateTime.tryParse(m['issuedAt']??'')??DateTime.now()); }